import { describe, expect, it } from 'vitest';
import { MIN_NORMALIZED_POWER, generateCandidates, planShot, scoreCandidate } from './BotPlanner';
import { BOT_PROFILES } from './BotProfiles';
import type { BotPlanningContext, BotProfile, PathAnalysis } from './types';
import type { Hole } from '../courses/types';

const hole: Hole = {
  id: 'test-hole',
  name: 'Test Hole',
  par: 3,
  spawn: { x: 0, y: 0, z: -8 },
  cup: { position: { x: 0, y: 0, z: 8 }, radius: 0.6, captureDepth: 0.4 },
  bounds: { min: { x: -10, y: -2, z: -12 }, max: { x: 10, y: 6, z: 12 } },
  surfaces: [
    {
      id: 'fairway',
      transform: { position: { x: 0, y: 0, z: 0 } },
      shape: 'box',
      size: { x: 20, y: 0.5, z: 24 },
      material: 'green',
    },
  ],
  obstacles: [],
};

const cleanAnalysis: PathAnalysis = {
  holed: false,
  outOfBounds: false,
  hazardPenalty: 0,
  obstacleHits: 0,
  estimatedTravelDistance: 16,
  estimatedRemainingDistance: 1.5,
};

const profileByRank = (rank: BotProfile['rank']): BotProfile => {
  const found = BOT_PROFILES.find((bot) => bot.rank === rank);
  if (!found) throw new Error(`no bot profile for rank ${rank}`);
  return found;
};

const context = (overrides: Partial<BotPlanningContext> = {}): BotPlanningContext => ({
  playerId: 'bot-1',
  hole,
  ballPosition: hole.spawn,
  clientSequence: 7,
  issuedAt: 1_700_000_000_000,
  seed: 'seed-a',
  ...overrides,
});

describe('candidate scoring penalties', () => {
  const bot = profileByRank('Pro');

  it('penalises out of bounds, hazards and obstacle hits relative to a clean path', () => {
    const clean = scoreCandidate(hole, hole.spawn, bot, cleanAnalysis);
    const outOfBounds = scoreCandidate(hole, hole.spawn, bot, { ...cleanAnalysis, outOfBounds: true });
    const hazard = scoreCandidate(hole, hole.spawn, bot, { ...cleanAnalysis, hazardPenalty: 2 });
    const obstacles = scoreCandidate(hole, hole.spawn, bot, { ...cleanAnalysis, obstacleHits: 3 });

    expect(outOfBounds).toBeLessThan(clean);
    expect(hazard).toBeLessThan(clean);
    expect(obstacles).toBeLessThan(clean);
    expect(hazard).toBeLessThan(scoreCandidate(hole, hole.spawn, bot, { ...cleanAnalysis, hazardPenalty: 1 }));
  });

  it('rewards holing out above every non-holed alternative', () => {
    const holed = scoreCandidate(hole, hole.spawn, bot, { ...cleanAnalysis, holed: true, estimatedRemainingDistance: 0 });
    expect(holed).toBeGreaterThan(scoreCandidate(hole, hole.spawn, bot, { ...cleanAnalysis, estimatedRemainingDistance: 0.1 }));
  });

  it('applies softer hazard penalties to risk tolerant bots', () => {
    const careful = BOT_PROFILES.reduce((a, b) => (a.skill.riskTolerance <= b.skill.riskTolerance ? a : b));
    const bold = BOT_PROFILES.reduce((a, b) => (a.skill.riskTolerance >= b.skill.riskTolerance ? a : b));
    const hazardous: PathAnalysis = { ...cleanAnalysis, hazardPenalty: 1 };

    const carefulDrop = scoreCandidate(hole, hole.spawn, careful, cleanAnalysis) - scoreCandidate(hole, hole.spawn, careful, hazardous);
    const boldDrop = scoreCandidate(hole, hole.spawn, bold, cleanAnalysis) - scoreCandidate(hole, hole.spawn, bold, hazardous);

    expect(carefulDrop).toBeGreaterThan(0);
    expect(boldDrop).toBeLessThan(carefulDrop);
  });
});

describe('candidate generation', () => {
  it('produces at least thirty legal candidates', () => {
    const candidates = generateCandidates(hole, hole.spawn, profileByRank('Master'), () => 0.5);
    expect(candidates.length).toBeGreaterThanOrEqual(30);
    for (const candidate of candidates) {
      expect(candidate.normalizedPower).toBeGreaterThanOrEqual(MIN_NORMALIZED_POWER);
      expect(candidate.normalizedPower).toBeLessThanOrEqual(1);
      expect(Math.hypot(candidate.direction.x, candidate.direction.z)).toBeCloseTo(1, 6);
    }
  });

  it('scales the candidate pool with simulation samples', () => {
    const rookie = generateCandidates(hole, hole.spawn, profileByRank('Rookie'), () => 0.5).length;
    const legend = generateCandidates(hole, hole.spawn, profileByRank('Legend'), () => 0.5).length;
    expect(legend).toBeGreaterThanOrEqual(rookie);
  });
});

describe('planShot', () => {
  const bot = profileByRank('Pro');

  it('is deterministic for a given seed', () => {
    const first = planShot(bot, context());
    const second = planShot(bot, context());
    expect(second.command).toEqual(first.command);
    expect(second.chosenCandidate.score).toBe(first.chosenCandidate.score);
  });

  it('emits a legal ShotCommand that mirrors the planning context', () => {
    const plan = planShot(bot, context({ clientSequence: 11, issuedAt: 1_700_000_000_500 }));
    expect(plan.command.playerId).toBe('bot-1');
    expect(plan.command.holeId).toBe(hole.id);
    expect(plan.command.clientSequence).toBe(11);
    expect(plan.command.issuedAt).toBe(1_700_000_000_500);
    expect(plan.command.normalizedPower).toBeGreaterThanOrEqual(MIN_NORMALIZED_POWER);
    expect(plan.command.normalizedPower).toBeLessThanOrEqual(1);
    expect(Math.hypot(plan.command.direction.x, plan.command.direction.z)).toBeCloseTo(1, 6);
    expect(Number.isFinite(plan.command.direction.y)).toBe(true);
  });

  it('chooses a candidate from its own pool that beats the average score', () => {
    const plan = planShot(bot, context({ seed: 'seed-b' }));
    expect(plan.candidates.length).toBeGreaterThanOrEqual(30);
    expect(plan.candidates).toContain(plan.chosenCandidate);
    const average = plan.candidates.reduce((sum, candidate) => sum + candidate.score, 0) / plan.candidates.length;
    expect(plan.chosenCandidate.score).toBeGreaterThanOrEqual(average);
  });

  it('keeps every rank inside the arena when a clean line exists', () => {
    for (const rank of ['Rookie', 'Amateur', 'Pro', 'Master', 'Legend'] as const) {
      const plan = planShot(profileByRank(rank), context({ seed: `seed-${rank}` }));
      expect(plan.chosenCandidate.analysis.outOfBounds).toBe(false);
      expect(plan.chosenCandidate.analysis.hazardPenalty).toBe(0);
    }
  });

  it('leaves stronger bots no further from the cup than weaker bots on average', () => {
    const averageRemaining = (profile: BotProfile): number => {
      const seeds = Array.from({ length: 12 }, (_, index) => `run-${index}`);
      const total = seeds.reduce((sum, seed) => sum + planShot(profile, context({ seed })).chosenCandidate.analysis.estimatedRemainingDistance, 0);
      return total / seeds.length;
    };
    expect(averageRemaining(profileByRank('Legend'))).toBeLessThanOrEqual(averageRemaining(profileByRank('Rookie')) + 1e-9);
  });
});
